import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.G0y0PQA7.js";const u=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/index.md","filePath":"en/features/index.md"}'),o={name:"en/features/index.md"};function i(s,e,d,l,h,g){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>Detailed reference for every menu and feature area, with all options and behavior. Pick the page for the feature you need and read just the sections you want. To follow a task in a few steps, see <a href="/relio/en/quick/start">Quick start</a>. Inside the app, Help › User guide (<kbd>F1</kbd>) has a short guide.</p><h2 id="the-window" tabindex="-1">The window <a class="header-anchor" href="#the-window" aria-label="Permalink to &quot;The window&quot;">​</a></h2><ul><li><strong>Menus</strong> — File · Edit · View · Arrange · Model · Tools · Help. <a href="/relio/en/features/file">File</a> · <a href="/relio/en/features/edit">Edit</a> · <a href="/relio/en/features/canvas">Canvas and palette</a> · <a href="/relio/en/features/model">Model menu</a> · <a href="/relio/en/features/preferences">Settings</a> · <a href="/relio/en/features/troubleshooting">Help and troubleshooting</a></li><li><strong>Toolbar</strong> — New diagram, open and save; delete, undo and redo; zoom in, zoom out, fit and zoom level; grid and snap to grid; Export to DB; <strong>Align ▾</strong>; background color. <a href="/relio/en/features/canvas#arrange-menu">Canvas and palette › Arrange menu</a></li><li><strong>Palette</strong> (left) — Drawing tools. <a href="/relio/en/features/canvas#palette-tools">Canvas and palette › Palette tools</a></li><li><strong>Canvas</strong> — Where you draw the diagram. <a href="/relio/en/features/canvas">Canvas and palette</a></li><li><strong>Outline</strong> (top right) — Lists of group columns, word dictionary, tables, views, triggers, sequences, indexes and tablespaces, with counts. <a href="/relio/en/features/canvas#outline">Canvas and palette › Outline</a></li><li><strong>Minimap</strong> (bottom right) — The whole diagram in small. Drag the visible-area rectangle to move the view. <a href="/relio/en/features/canvas#zoom-and-pan">Canvas and palette › Zoom and pan</a></li><li><strong>Category tabs</strong> (bottom) — &quot;All&quot; plus one tab per category. The design check <strong>Problems: …</strong> button sits at the right end of this row. <a href="/relio/en/features/categories">Categories</a></li><li><strong>Problem list</strong> (bottom panel) — Design check findings, file repairs and DDL warnings. <a href="/relio/en/features/check#problem-list">Design check and suggestions</a></li><li><strong>Status bar</strong> (very bottom) — From the left: target database and version (click to open the options dialog), counts of tables, columns and relationships, the categories in view (for several: <code>Categories: Members + Orders · new nodes → Orders</code>); on the right: the Git branch name (for files in a repository — click for Git history), <strong>Disable column clicks</strong> (when on — click to turn it off), task hints, the number of selected objects, the zoom level and the Relio version.</li></ul><p>In this guide, a <strong>node</strong> is any box placed on the canvas — a table, view, note, category area or image. Relationship lines and note connection lines are called <strong>connection lines</strong>.</p><h2 id="where-to-look" tabindex="-1">Where to look <a class="header-anchor" href="#where-to-look" aria-label="Permalink to &quot;Where to look&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you want to do</th><th>Where to look</th></tr></thead><tbody><tr><td>Start a new model from an SQL or DBML file</td><td><a href="/relio/en/quick/import-start">Start from SQL or DBML</a> · <a href="/relio/en/features/import">Import and other formats</a></td></tr><tr><td>Bring a production database structure into a model</td><td><a href="/relio/en/features/database#import-from-db">Databases › Import from DB</a></td></tr><tr><td>Apply only the changes to a database (ALTER)</td><td><a href="/relio/en/features/git#generating-migration-sql">Git and merging › Generating migration SQL</a></td></tr><tr><td>Make a table document in Excel</td><td><a href="/relio/en/features/export#excel">Export › Excel</a></td></tr><tr><td>Make Mermaid or DBML to paste into another tool</td><td><a href="/relio/en/features/export#text-formats-dbml-mermaid-markdown-model-json">Export › Text formats</a></td></tr><tr><td>Bundle common columns such as created date and modified by</td><td><a href="/relio/en/features/model#manage-groups-and-global-groups">Model menu › Manage groups</a></td></tr><tr><td>Rename many things at once</td><td><a href="/relio/en/features/edit#find-and-replace-dialog">Edit › Find and replace dialog</a></td></tr><tr><td>Edit column properties of many tables in one grid</td><td><a href="/relio/en/features/edit#edit-all-properties">Edit › Edit all properties</a></td></tr><tr><td>Add many columns at once from an Excel table</td><td><a href="/relio/en/features/dialogs#quick-entry">Properties dialogs › Quick entry</a></td></tr><tr><td>See only part of a big model</td><td><a href="/relio/en/features/categories">Categories</a></td></tr><tr><td>Find a table quickly in a big model</td><td><a href="/relio/en/features/find">Find and highlight</a></td></tr><tr><td>Change the target database version</td><td><a href="/relio/en/features/model#options">Model menu › Options</a></td></tr><tr><td>Fix design problems in one go</td><td><a href="/relio/en/features/check#problem-list">Design check and suggestions › Problem list</a></td></tr><tr><td>Compare two versions of a model</td><td><a href="/relio/en/features/git#comparison-view">Git and merging › Comparison view</a></td></tr><tr><td>Resolve a Git merge conflict</td><td><a href="/relio/en/features/git#merging">Git and merging › Merging</a></td></tr><tr><td>Keep a snapshot of the current state and go back to it</td><td><a href="/relio/en/features/model#change-history">Model menu › Change history</a></td></tr><tr><td>Clean up unused words</td><td><a href="/relio/en/features/model#word-dictionary-and-word-properties">Model menu › Word dictionary</a></td></tr><tr><td>Open a damaged file</td><td><a href="/relio/en/features/file#opening-a-damaged-file">File › Opening a damaged file</a></td></tr><tr><td>Recover after Relio stopped unexpectedly</td><td><a href="/relio/en/features/file#automatic-backup-and-recovery">File › Automatic backup and recovery</a></td></tr><tr><td>Give the canvas more room</td><td><a href="/relio/en/features/canvas#panels-and-the-start-screen">Canvas and palette › Panels and the start screen</a></td></tr><tr><td>Change shortcuts</td><td><a href="/relio/en/features/preferences#shortcuts">Settings › Shortcuts</a></td></tr><tr><td>Change the theme or display language</td><td><a href="/relio/en/features/preferences#display">Settings › Display</a></td></tr><tr><td>Run design checks or generate DDL in CI</td><td><a href="/relio/en/features/cli#using-it-in-ci">Command line › Using it in CI</a></td></tr><tr><td>Get a new version</td><td><a href="/relio/en/features/update">Updates</a></td></tr><tr><td>Report a problem</td><td><a href="/relio/en/features/troubleshooting#reporting-a-problem">Help and troubleshooting › Reporting a problem</a></td></tr></tbody></table><h2 id="drawing-and-editing" tabindex="-1">Drawing and editing <a class="header-anchor" href="#drawing-and-editing" aria-label="Permalink to &quot;Drawing and editing&quot;">​</a></h2><ul><li><a href="/relio/en/features/file">File</a> — Everything on the File menu and document tabs: new, open, save, recent files, automatic backup and opening damaged files.</li><li><a href="/relio/en/features/edit">Edit</a> — The Edit menu: cut, copy and paste, undo, the find and replace dialog, Edit all properties and more.</li><li><a href="/relio/en/features/canvas">Canvas and palette</a> — Reading the canvas, the palette tools (select, hand, table, view, relationships, note, category, image), selecting and moving, the Arrange menu, View menu settings, zoom and pan, and the outline.</li><li><a href="/relio/en/features/dialogs">Properties dialogs</a> — Table properties (columns, indexes, composite unique keys, advanced settings), column properties, Quick entry, index, view and relationship properties, and the note connection and image dialogs.</li><li><a href="/relio/en/features/model">Model menu</a> — Word dictionary, groups and global groups, sequences, triggers and tablespaces, options, change history, translation management, test data and model properties.</li><li><a href="/relio/en/features/categories">Categories</a> — Creating category areas, Manage categories, the category tabs, viewing several categories together, and showing referencing tables.</li><li><a href="/relio/en/features/find">Find and highlight</a> — The find bar and match modes, Hangul initial-consonant search, hover and selection connection highlights, and highlight settings.</li><li><a href="/relio/en/features/check">Design check and suggestions</a> — Design check rules and marks, fixing and ignoring in the problem list, suggestions while typing, and relationship name matching.</li></ul><h2 id="export-and-integration" tabindex="-1">Export and integration <a class="header-anchor" href="#export-and-integration" aria-label="Permalink to &quot;Export and integration&quot;">​</a></h2><ul><li><a href="/relio/en/features/ddl">DDL</a> — The DDL export dialog: target database and version, what to generate, environment, encoding and line breaks, and version-specific syntax warnings.</li><li><a href="/relio/en/features/export">Export</a> — Excel, HTML, image, dictionary, test data, Java, DBML, Mermaid, Markdown and model JSON exports, and printing.</li><li><a href="/relio/en/features/import">Import and other formats</a> — Importing from SQL, DBML, Mermaid and Markdown, importing from another .erm file, where to import and what to do when names clash.</li><li><a href="/relio/en/features/database">Databases</a> — Database connections and the connection list, Import from DB, Export to DB, preparing Oracle and ODBC, and how passwords are stored.</li><li><a href="/relio/en/features/git">Git and merging</a> — Comparing two files and migration SQL, Git history, the three-way merge view, and the Git merge driver.</li></ul><h2 id="settings-and-help" tabindex="-1">Settings and help <a class="header-anchor" href="#settings-and-help" aria-label="Permalink to &quot;Settings and help&quot;">​</a></h2><ul><li><a href="/relio/en/features/preferences">Settings</a> — General (language, theme, backup, highlight, updates), global groups, translation dictionaries, Excel templates, DB connections, design check, shortcuts and passwords.</li><li><a href="/relio/en/features/cli">Command line</a> — The relio export, import, diff, merge, lint and db commands and their options, exit codes, and using them in builds and CI.</li><li><a href="/relio/en/features/update">Updates</a> — Automatic checks for new versions, Check for updates, installing from inside Relio, and updating the portable version.</li><li><a href="/relio/en/features/troubleshooting">Help and troubleshooting</a> — The Help menu (user guide, what&#39;s new, About Relio, open source licenses), what to do when a file does not open, Relio stops unexpectedly or a database connection fails, the diagnostic log, reporting a problem, and where your data is stored.</li></ul>',13)])])}const f=t(o,[["render",i]]);export{u as __pageData,f as default};
